 sf=B/'results/gf180_independent_bank_pair_v4_access_summary_v1.json';s=json.loads(sf.read_text());rp=R/s['report'];r=json.loads(rp.read_text());data=rp.with_suffix('.dat');w=np.loadtxt(data,skiprows=1);t=w[:,0];base=np.array([np.interp(1e-6,t,w[:,i+1]) for i in range(128)]);ii=[i for i in range(128) if not(i<8 or i>=120)];mask=t>=1e-6;delta=w[mask][:,np.array(ii)+1]-base[ii];j,k=np.unravel_index(np.argmax(abs(delta)),delta.shape);out=B/'results/gf180_independent_bank_pair_v4_trace_review_v1.json';assert not out.exists()
